package com.example.bikerental; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="support_tickets") public class SupportTicket { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String username; @Column(nullable=false) private String subject; @Column(nullable=false,length=2000) private String message; @Column(nullable=false) private String status="OPEN"; private LocalDateTime createdAt=LocalDateTime.now(); @Column(length=2000) private String adminReply; public SupportTicket(){} public SupportTicket(String u,String s,String m){username=u;subject=s;message=m;} public Long getId(){return id;} public String getUsername(){return username;} public String getSubject(){return subject;} public String getMessage(){return message;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public String getAdminReply(){return adminReply;} public void setAdminReply(String v){adminReply=v;} }